export const BUREVI_NETCDF_BASE64 = "";

export function getBureviFallbackBlob(): Blob {
  const byteChars = atob(BUREVI_NETCDF_BASE64);
  const byteNumbers = new Uint8Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) {
    byteNumbers[i] = byteChars.charCodeAt(i);
  }
  return new Blob([byteNumbers], { type: "application/x-netcdf" });
}
